app.post("/api/auth/send-code", async (req, res) => {
  try {
    const { email: email3, type = "register" } = req.body;
    if (!email3) {
      return res.status(400).json({ success: false, error: "Email is required" });
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email3)) {
      return res.status(400).json({ success: false, error: "Invalid email format" });
    }
    const client2 = getSupabaseClient();
    if (!client2) {
      return res.status(500).json({ success: false, error: "Database not configured" });
    }
    if (type === "register") {
      const { data: existingApp } = await client2.from("author_applications").select("id, status").eq("email", email3).single();
      if (existingApp) {
        if (existingApp.status === "pending") {
          return res.status(400).json({
            success: false,
            error: "You already have a pending application. Please wait for review."
          });
        }
        if (existingApp.status === "approved") {
          return res.status(400).json({
            success: false,
            error: "This email is already registered. Please login instead."
          });
        }
      }
    }
    const code = generateVerificationCode();
    const expiresAt = new Date(Date.now() + 10 * 60 * 1e3);
    await client2.from("email_verification_codes").update({ is_used: true }).eq("email", email3).eq("type", type).eq("is_used", false);
    const { error: insertError } = await client2.from("email_verification_codes").insert({
      email: email3,
      code,
      type,
      expires_at: expiresAt.toISOString()
    });
    if (insertError) {
      console.error("Failed to save verification code:", insertError);
      return res.status(500).json({ success: false, error: "Failed to generate code" });
    }
    const sent = await sendVerificationCode(email3, code, type);
    if (!sent) {
      return res.status(500).json({
        success: false,
        error: "Failed to send verification email. Please try again later."
      });
    }
    res.json({
      success: true,
      message: "Verification code sent to your email",
      expiresIn: 600
      // 10分钟
    });
  } catch (error40) {
    console.error("Send verification code error:", error40);
    res.status(500).json({ success: false, error: "Failed to send verification code" });
  }
});
