app.post("/api/author/:id/send-bind-email-code", async (req, res) => {
  try {
    const { id: id2 } = req.params;
    const { new_email } = req.body;
    if (!new_email) {
      return res.status(400).json({ success: false, error: "New email is required" });
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(new_email)) {
      return res.status(400).json({ success: false, error: "Invalid email format" });
    }
    const client2 = getSupabaseClient();
    if (!client2) {
      return res.status(500).json({ success: false, error: "Database not configured" });
    }
    const { data: existingUser } = await client2.from("authors").select("id").eq("email", new_email).neq("id", id2).single();
    if (existingUser) {
      return res.status(400).json({
        success: false,
        error: "This email is already in use by another account"
      });
    }
    const code = Math.floor(1e5 + Math.random() * 9e5).toString();
    const expiresAt = new Date(Date.now() + 10 * 60 * 1e3);
    await client2.from("email_verification_codes").update({ is_used: true }).eq("email", new_email).eq("type", "bind_email").eq("is_used", false);
    const { error: insertError } = await client2.from("email_verification_codes").insert({
      email: new_email,
      code,
      type: "bind_email",
      expires_at: expiresAt.toISOString()
    });
    if (insertError) {
      console.error("Failed to save verification code:", insertError);
      return res.status(500).json({ success: false, error: "Failed to generate code" });
    }
    const sent = await sendVerificationCode(new_email, code, "bind_email");
    if (!sent) {
      return res.status(500).json({
        success: false,
        error: "Failed to send verification email. Please try again later."
      });
    }
    res.json({
      success: true,
      message: "Verification code sent to your new email address",
      // 开发环境返回验证码方便测试
      ...process.env.NODE_ENV === "development" && { devCode: code }
    });
  } catch (error40) {
    console.error("Send bind email code error:", error40);
    res.status(500).json({ success: false, error: "Failed to send verification code" });
  }
});
